db = db*0.98 + bass*0.2; // dampener
bb = bb + db*0.1; // accumulation, replace time expressions with this ;)

dt = dt*0.98 + treb*0.2;
tt = tt + dt*0.1;

dm = dm*0.98 + mid*0.2;
mm = mm + dm*0.1;


//***** [q11-q18] variables for Flexis caleidoscope shader code *****

// change
q13 = 0.5 + sin((bb-mm)*0.1)*0.25; // center x
q14 = 0.5 + sin((tt-mm)*0.1)*0.25; // center y
w = (bb-tt)*0.1;                   // angle
q16 = 0.25 - (db-dt)*0.025;        // size

//don't change
q11 = sin(w);
q12 = cos(w);
q17 = sin(-w);
q18 = cos(-w);
q15 = 1/q16;

